text(await tools.exec_command({cmd:"$ErrorActionPreference = 'Stop'
$specText = Get-Content -Raw -Encoding UTF8 sr-smoke/spec.md
$timestamp = [DateTime]::UtcNow.ToString("yyyy-MM-ddTHH:mm:ss.fffffff'Z'", [Globalization.CultureInfo]::InvariantCulture)
$block = [regex]::Match($specText, '(?s)```text\r?\n(.*?)\r?\n```').Groups[1].Value.Replace("`r`n", "`n")
$body = $block.Replace('<current UTC ISO 8601 timestamp ending in Z>', $timestamp) + "`n"
[IO.File]::WriteAllText((Join-Path (Get-Location) 'evidence/native-101.md'), $body, [Text.UTF8Encoding]::new($false))
Write-Output ('UTC_GENERATED_AT=' + $timestamp)
powershell.exe -NoProfile -ExecutionPolicy Bypass -File ./sr-smoke/check.ps1
$checkerExit = $LASTEXITCODE
Write-Output ('CHECKER_EXIT=' + $checkerExit)
if ($checkerExit -ne 0) { exit $checkerExit }
$bytes = [IO.File]::ReadAllBytes((Join-Path (Get-Location) 'evidence/native-101.md'))
if ($bytes.Length -ge 3 -and $bytes[0] -eq 239 -and $bytes[1] -eq 187 -and $bytes[2] -eq 191) { throw 'Unexpected UTF-8 BOM' }
$actual = [IO.File]::ReadAllText((Join-Path (Get-Location) 'evidence/native-101.md'), [Text.UTF8Encoding]::new($false, $true))
if ($actual -cne $body -or $actual.Split([char]10).Count -ne 6) { throw 'Content verification failed' }
Write-Output 'UTF8_NO_BOM_AND_EXACT_FIVE_LINES=PASS'
git diff --check
if ($LASTEXITCODE -ne 0) { exit $LASTEXITCODE }
$paths = @(git diff --name-only HEAD)
if ($LASTEXITCODE -ne 0) { exit $LASTEXITCODE }
if ($paths.Count -ne 1 -or $paths[0] -ne 'evidence/native-101.md') { throw 'Unexpected changed file scope' }
git status --short
git diff -- evidence/native-101.md",shell:"C:\Windows\System32\WindowsPowerShell\v1.0\powershell.exe",max_output_tokens:3000}));

